package uy.utu.biblioteca;
import java.sql.*;import java.time.LocalDate;import java.util.*;
public class PrestamoDAO {
 public List<Prestamo> listar(String filtro)throws SQLException{List<Prestamo> l=new ArrayList<>();String q="SELECT p.id,a.nombre alumno,b.titulo libro,u.username usuario,p.fecha_prestamo,p.fecha_devolucion,p.estado FROM prestamos p JOIN alumnos a ON a.id=p.alumno_id JOIN libros b ON b.id=p.libro_id JOIN usuarios u ON u.id=p.usuario_id WHERE a.nombre LIKE ? OR b.titulo LIKE ? OR p.estado LIKE ? ORDER BY p.fecha_prestamo DESC";try(Connection c=Database.conectar();PreparedStatement p=c.prepareStatement(q)){String x="%"+(filtro==null?"":filtro.trim())+"%";p.setString(1,x);p.setString(2,x);p.setString(3,x);try(ResultSet r=p.executeQuery()){while(r.next()){java.sql.Date d=r.getDate("fecha_devolucion");l.add(new Prestamo(r.getInt("id"),r.getString("alumno"),r.getString("libro"),r.getString("usuario"),r.getDate("fecha_prestamo").toLocalDate(),d==null?null:d.toLocalDate(),r.getString("estado")));}}}return l;}
 public void crear(int alumnoId,int libroId,int usuarioId)throws Exception{try(Connection c=Database.conectar()){c.setAutoCommit(false);try{int stock;try(PreparedStatement p=c.prepareStatement("SELECT stock FROM libros WHERE id=? FOR UPDATE")){p.setInt(1,libroId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new ValidacionException("El libro no existe.");stock=r.getInt(1);}}if(stock<1)throw new ValidacionException("No hay ejemplares disponibles.");try(PreparedStatement p=c.prepareStatement("INSERT INTO prestamos(alumno_id,libro_id,usuario_id,fecha_prestamo,estado) VALUES(?,?,?,CURRENT_DATE,'ACTIVO')")){p.setInt(1,alumnoId);p.setInt(2,libroId);p.setInt(3,usuarioId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE libros SET stock=stock-1 WHERE id=?")){p.setInt(1,libroId);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
 public void devolver(int prestamoId)throws Exception{try(Connection c=Database.conectar()){c.setAutoCommit(false);try{int libroId;try(PreparedStatement p=c.prepareStatement("SELECT libro_id,estado FROM prestamos WHERE id=? FOR UPDATE")){p.setInt(1,prestamoId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new ValidacionException("No existe el préstamo.");if(!"ACTIVO".equals(r.getString("estado")))throw new ValidacionException("El préstamo ya fue devuelto.");libroId=r.getInt("libro_id");}}try(PreparedStatement p=c.prepareStatement("UPDATE prestamos SET estado='DEVUELTO',fecha_devolucion=CURRENT_DATE WHERE id=?")){p.setInt(1,prestamoId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE libros SET stock=stock+1 WHERE id=?")){p.setInt(1,libroId);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
 public void eliminar(int prestamoId)throws Exception{try(Connection c=Database.conectar()){c.setAutoCommit(false);try{int libroId;String estado;try(PreparedStatement p=c.prepareStatement("SELECT libro_id,estado FROM prestamos WHERE id=? FOR UPDATE")){p.setInt(1,prestamoId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new ValidacionException("No existe el préstamo.");libroId=r.getInt("libro_id");estado=r.getString("estado");}}try(PreparedStatement p=c.prepareStatement("DELETE FROM prestamos WHERE id=?")){p.setInt(1,prestamoId);p.executeUpdate();}if("ACTIVO".equals(estado)){try(PreparedStatement p=c.prepareStatement("UPDATE libros SET stock=stock+1 WHERE id=?")){p.setInt(1,libroId);p.executeUpdate();}}c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
 public List<String[]> reportePorLibro()throws SQLException{List<String[]> l=new ArrayList<>();String q="SELECT b.titulo,COUNT(p.id) cantidad,COALESCE(SUM(p.estado='ACTIVO'),0) activos FROM libros b LEFT JOIN prestamos p ON p.libro_id=b.id GROUP BY b.id,b.titulo ORDER BY cantidad DESC";try(Connection c=Database.conectar();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())l.add(new String[]{r.getString(1),r.getString(2),r.getString(3)});}return l;}
}
